def min_operations(nums):
    M = max(nums)
    # spf[x] = smallest prime factor of x (spf[x] = x for primes, and for 1)
    spf = list(range(M + 1))
    i = 2
    while i * i <= M:
        if spf[i] == i:
            for j in range(i * i, M + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1

    n = len(nums)
    ans = 0
    # Process from right to left, so after each step, nums[i+1] is fixed.
    for i in range(n - 2, -1, -1):
        if nums[i] > nums[i + 1]:
            # One operation turns nums[i] into its smallest prime factor
            # (a prime or 1 stays the same, so it is then still too large).
            nums[i] = spf[nums[i]]
            ans += 1
            if nums[i] > nums[i + 1]:
                return -1
    return ans
